test('addLine does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  const invoiceCopy = JSON.stringify(invoice);
  addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(JSON.stringify(invoice), invoiceCopy);
});

test('removeLine removes a line from a draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  const r2 = removeLine(invoice, 'DES-HOUR');
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine reports LINE_NOT_FOUND if SKU not on invoice', () => {
